const (
	// source compatibility alias
	RLIMIT_RSS = 5
	// locked-in-memory address space
	RLIMIT_MEMLOCK = 6
	// number of processes
	RLIMIT_NPROC = 7
)

// number of open files
const RLIMIT_NOFILE = 8

// total number of resource limits
const RLIM_NLIMITS = 9

