// 0777
const ACCESSPERMS = 511

// 7777
const ALLPERMS = 4095

// 0666
const DEFFILEMODE = 438

// block size used in the stat struct
const S_BLKSIZE = 512

// Definitions of flags stored in file flags word.
//
// Super-user and owner changeable flags.
const (
	UF_SETTABLE = 65535
	// do not dump file
	UF_NODUMP = 1
	// file may not be changed
	UF_IMMUTABLE = 2
	// writes to file may only append
	UF_APPEND = 4
	// directory is opaque wrt. union
	UF_OPAQUE = 8
)

// file is compressed (some file-systems)
const UF_COMPRESSED = 32

// UF_TRACKED is used for dealing with document IDs.  We no longer issue
//
//	notifications for deletes or renames for files which have UF_TRACKED set.
const UF_TRACKED = 64

// entitlement required for reading
const UF_DATAVAULT = 128

// Bits 0x0100 through 0x4000 are currently undefined.
const UF_HIDDEN = 32768

// Super-user changeable flags.
const (
	SF_SUPPORTED = 10420224
	// mask of superuser changeable flags
	SF_SETTABLE = 1073676288
	// mask of system read-only synthetic flags
	SF_SYNTHETIC = 3221225472
	// file is archived
	SF_ARCHIVED = 65536
	// file may not be changed
	SF_IMMUTABLE = 131072
	// writes to file may only append
	SF_APPEND = 262144
	// entitlement required for writing
	SF_RESTRICTED = 524288
	// Item may not be removed, renamed or mounted on
	SF_NOUNLINK = 1048576
)

// file is a firmlink
const SF_FIRMLINK = 8388608

// Synthetic flags.
//
// These are read-only.  We keep them out of SF_SUPPORTED so that
// attempts to set them will fail.
const SF_DATALESS = 1073741824

// Extended flags ("EF") returned by ATTR_CMNEXT_EXT_FLAGS from getattrlist/getattrlistbulk
const (
	EF_MAY_SHARE_BLOCKS = 1
	// file has no xattrs at all
	EF_NO_XATTRS = 2
	// file is a sync root for iCloud
	EF_IS_SYNC_ROOT = 4
	// file is purgeable
	EF_IS_PURGEABLE = 8
	// file has at least one sparse region
	EF_IS_SPARSE = 16
	// a synthetic directory/symlink
	EF_IS_SYNTHETIC = 32
	// file shares all of its blocks with another file
	EF_SHARES_ALL_BLOCKS = 64
)

const (
	UTIME_NOW  = -1
	UTIME_OMIT = -2
)

